module and2(
    input  wire a,
    input  wire b,
    output wire y
);

assign y = a & b;

endmodule

module mux2(
    input  wire a,
    input  wire b,
    input  wire sel,
    output wire y
);

assign y = sel ? b : a;

endmodule

module rising_edge_detect(
    input  wire clk,
    input  wire rst_n,
    input  wire sig_in,
    output wire rise_pulse
);

reg sig_d;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sig_d <= 1'b0;
    end else begin
        sig_d <= sig_in;
    end
end

assign rise_pulse = sig_in & ~sig_d;

endmodule

module two_one_fsm(
    input  wire clk,
    input  wire rst_n,
    input  wire din,
    output reg  hit
);

localparam S0 = 1'b0;
localparam S1 = 1'b1;

reg state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S0;
        hit   <= 1'b0;
    end else begin
        hit <= 1'b0;
        case (state)
            S0: begin
                state <= din ? S1 : S0;
            end
            S1: begin
                if (din) begin
                    hit <= 1'b1;
                    state <= S1;
                end else begin
                    state <= S0;
                end
            end
            default: begin
                state <= S0;
            end
        endcase
    end
end

endmodule
